function getRandomBookImage() {
    // Return random image from reliable sources
    const image = BOOK_IMAGES[Math.floor(Math.random() * BOOK_IMAGES.length)];
    // Add a fallback placeholder if image fails
    return image || 'data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 width=%22300%22 height=%22400%22%3E%3Crect fill=%22%236366f1%22 width=%22300%22 height=%22400%22/%3E%3Ctext x=%2250%25%22 y=%2250%25%22 font-size=%2224%22 fill=%22white%22 text-anchor=%22middle%22 dominant-baseline=%22middle%22%3EBook Cover%3C/text%3E%3C/svg%3E';
}

