// Helper function to get products (simulates JSP data binding)
function getProducts() {
    return PRODUCTS_DATA;
}

function getProductById(id) {
    return PRODUCTS_DATA.find(p => p.id === parseInt(id));
}

function getFeaturedProducts() {
    return PRODUCTS_DATA.filter(p => p.featured).slice(0, 6);
}

function getBestsellerProducts() {
    return PRODUCTS_DATA.filter(p => p.bestseller).slice(0, 6);
}

function getNewProducts() {
    return PRODUCTS_DATA.filter(p => p.new).slice(0, 6);
}

function getProductsByCategory(categoryId) {
    return PRODUCTS_DATA.filter(p => p.categoryId === categoryId);
}

function getProductsByAuthor(authorId) {
    return PRODUCTS_DATA.filter(p => p.authorId === authorId);
}

function getProductsByPublisher(publisherId) {
    return PRODUCTS_DATA.filter(p => p.publisherId === publisherId);
}

// Helper to get unique authors from products
function getUniqueAuthors() {
    const unique = {};
    PRODUCTS_DATA.forEach(p => {
        if (p.authorName && !unique[p.authorName]) {
            unique[p.authorName] = p.authorId;
        }
    });
    return Object.entries(unique).map(([name, id]) => ({ id, name }));
}

// Helper to get unique publishers from products
function getUniquePublishers() {
    const unique = {};
    PRODUCTS_DATA.forEach(p => {
        if (p.publisherName && !unique[p.publisherName]) {
            unique[p.publisherName] = p.publisherId;
        }
    });
    return Object.entries(unique).map(([name, id]) => ({ id, name }));
}

